using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using the search tool
    2. Taking notes on key findings using the note-taking tool
    3. Performing multiple searches to cover different aspects of the topic
    4. Summarizing all findings into a coherent report

    Always take notes on important findings before moving to the next search.
    When you have gathered enough information, provide a final summary.
    """)
{
    Tools = [.. AIFunctionFactory.Create(researchTools)]
};

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"• {note}");
}

// --- Services and Tools ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void AddNote(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetNotes() => _notes;
}

public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a query. Returns a list of relevant results with titles, snippets, and URLs.")]
    public static IReadOnlyList<SearchResult> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing Search, Google Custom Search, etc.) for production use.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return
        [
            new($"Result 1 for '{query}'",
                $"This is a comprehensive overview covering key developments related to {query}. Researchers have made significant breakthroughs in this area recently.",
                $"https://example.com/search?q={Uri.EscapeDataString(query)}&r=1"),
            new($"Result 2 for '{query}'",
                $"A detailed analysis of {query} reveals emerging trends and challenges. Industry experts predict major advances in the near future.",
                $"https://example.com/search?q={Uri.EscapeDataString(query)}&r=2"),
            new($"Result 3 for '{query}'",
                $"Recent publications on {query} highlight practical applications and theoretical foundations that are driving innovation.",
                $"https://example.com/search?q={Uri.EscapeDataString(query)}&r=3"),
        ];
    }

    [Description("Save a research note for later reference. Use this to record key findings from searches.")]
    public string TakeNote(
        [Description("The content of the note to save")] string note)
    {
        Console.WriteLine($"  [Tool] Note taken: \"{note[..Math.Min(note.Length, 80)]}...\"");
        noteService.AddNote(note);
        return $"Note saved successfully. Total notes: {noteService.GetNotes().Count}";
    }
}

public sealed record SearchResult(string Title, string Snippet, string Url);

