builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient(modelId));

builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();
var researchTools = new ResearchTools(noteService);

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. AIFunctionFactory.Create(researchTools)],
};

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An agent that researches topics using web search and note-taking.",
