    });

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"Researching: {topic}\n");

var session = await agent.CreateSessionAsync("research-session");

var response = await agent.RunAsync(
    $"""
    Research the following topic and provide a comprehensive summary: {topic}

    Instructions:
    1. Search the web for relevant information (perform at least 2-3 searches on different aspects)
    2. Take notes on key findings after each search
    3. Once you have enough information, provide a final comprehensive summary
    """,
    session);

Console.WriteLine(response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant)?.Text
    ?? "No response generated.");

Console.WriteLine("\n--- Research Notes ---");
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"• {note}");
}

